receipt_format.schema:
{
  "task_id": "<kebab-case identifier>",
  "bot": "<bot-id>",
  "destructive": false,
  "commands": [
    { "cmd": "<exact command run>", "exit_code": 0 }
  ],
  "claims": [
    { "claim": "<what you assert is true>", "evidence_command_index": 0,
      "expects_failure": false }
  ],
  "unverified": [],
  "approvals": [
    { "operation": "<what was approved>", "approved_by": "<human>", "at": "<iso8601>" }
  ]
}
